/*
 * Firefly base styles — design tokens + motion foundation.
 * Installed by `firefly-base` as app/firefly.css. Import it right after Tailwind in app/globals.css:
 *
 *   @import "tailwindcss";
 *   @import "./firefly.css";
 *
 * Fonts: load Inter (--font-inter) and IBM Plex Mono (--font-plex-mono) with next/font in app/layout.tsx.
 * When a client's Figma has its own variables, change the VALUES here (keep the names) so every
 * installed component picks up the client palette.
 */
@theme {
  /* Text */
  --color-text-primary: #0a0a0a;
  --color-text-secondary: #515258;
  --color-text-tertiary: #696969;
  --color-text-quaternary: #878787;
  --color-text-placeholder: #9e9e9e;
  /* Grey half of two-tone headlines and muted copy. 3.0:1 on the page background (WCAG AA large text). */
  --color-text-muted: #919191;
  --color-text-nav: #6b6b6b;
  --color-text-inverse: #fafafa;
  --color-text-on-dark: #f5f7fa;

  /* Icons */
  --color-icon-primary: #0a0a0a;
  --color-icon-secondary: #636363;
  --color-icon-tertiary: #878787;
  --color-icon-quaternary: #b2b2b2;

  /* Surfaces */
  --color-surface-page: #fdfcfc;
  --color-surface-primary: #ffffff;
  --color-surface-secondary: #f8f8fb;
  --color-surface-muted: #f5f5f5;
  --color-surface-card-light: #f2f2f2;
  --color-surface-card-dark: #1b1b1b;
  --color-surface-inverse: #0a0a0a;
  --color-surface-dark: #0f1115;

  /* Borders */
  --color-border-04: #0000000a;
  --color-border-06: #0000000f;
  --color-border-10: #0000001a;
  --color-border-16: #00000029;
  --color-border-24: #0000003d;
  --color-border-light: #e8e8e8;
  --color-border-dark: #2a2a2a;
  --color-border-on-dark: #2a2f3a;
  --color-border-interactive: #3f51f4;

  /* Buttons (ElevenLabs-style pills: colour change on hover, no lift) */
  --color-button-primary: #0a0a0a;
  --color-button-primary-hover: #44403b;
  --color-button-content-primary: #ffffff;
  --color-button-secondary: #ffffff;
  --color-button-secondary-hover: #fdfcfc;
  --color-button-content-secondary: #0a0a0a;
  /* Hover / pressed layer under inactive tabs and ghost controls */
  --color-surface-pressed: #ebe8e4;
  /* Pagination dots */
  --color-pagination-dot: #d7d2cc;
  --color-pagination-active: #44403b;

  /* Status (tags, dots) */
  --color-status-positive: #166534;
  --color-status-positive-bg: #f0fdf4;
  --color-status-negative: #b91c1c;
  --color-status-negative-bg: #fff5f5;
  --color-status-warning: #b94020;
  --color-status-warning-bg: #fff1ec;

  /* Radii (named to avoid clashing with Tailwind's rounded-s / rounded-l side utilities) */
  --radius-chip: 6px;
  --radius-tile: 8px;
  --radius-frame: 12px;
  --radius-card: 14px;
  --radius-pill: 9999px;

  /* Shadows */
  --shadow-card-drop: 0 30px 70px 0 #0000000a;
  --shadow-soft: 0 16px 40px 0 #0000000f;
  /* Secondary buttons, tab indicators, icon buttons: a half-pixel ring + two soft drops (no border) */
  --shadow-button: 0 0 0 0.5px #00000020, 0 1px 1px 0 #0000000a, 0 2px 4px 0 #0000000a;

  /* Type */
  --font-sans: var(--font-inter), ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-mono: var(--font-plex-mono), ui-monospace, "SF Mono", Menlo, monospace;

  /* Motion */
  --ease-out-soft: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-standard: cubic-bezier(0.4, 0, 0.2, 1);
}

@layer base {
  html {
    -webkit-text-size-adjust: 100%;
    text-rendering: optimizeLegibility;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    scroll-padding-top: 80px;
  }
  @media (prefers-reduced-motion: no-preference) {
    html {
      scroll-behavior: smooth;
    }
  }
  body {
    background: var(--color-surface-page);
    color: var(--color-text-primary);
    font-family: var(--font-sans);
    overflow-x: clip;
  }
  :focus-visible {
    outline: 2px solid var(--color-border-interactive);
    outline-offset: 3px;
    border-radius: 4px;
  }
}

/*
 * Scroll reveals.
 * Content is fully visible by default (SSR, no JS, crawlers, reduced motion). Only when the
 * <MotionScript> head script adds `.motion-ok` to <html> are [data-reveal] elements hidden until
 * <Reveal> marks them `data-in`. Only transform + opacity animate.
 */
.motion-ok [data-reveal] {
  opacity: 0;
  transform: translate3d(0, var(--reveal-y, 20px), 0);
  transition:
    opacity 0.8s var(--ease-out-soft),
    transform 0.9s var(--ease-out-soft);
  transition-delay: var(--reveal-delay, 0ms);
  will-change: opacity, transform;
}
.motion-ok [data-reveal][data-in] {
  opacity: 1;
  transform: none;
}

/* Body of an accordion / step list fading in when its item opens */
@keyframes feature-in {
  from {
    opacity: 0;
    transform: translate3d(0, 6px, 0);
  }
}

/* Marquees: the track holds two identical copies and moves by half its width */
@keyframes marquee-left {
  from {
    transform: translate3d(0, 0, 0);
  }
  to {
    transform: translate3d(-50%, 0, 0);
  }
}
@keyframes marquee-right {
  from {
    transform: translate3d(-50%, 0, 0);
  }
  to {
    transform: translate3d(0, 0, 0);
  }
}

/**
 * Put <MotionScript /> inside <head> in app/layout.tsx.
 *
 * Enables reveal animations only when JS runs and the user allows motion: adds `motion-ok`
 * to <html>. Failsafe: if the app never hydrates (no <Reveal> mounted), everything is
 * revealed after 3s so content is never stuck hidden.
 */
export const motionScript = `(function(){try{var d=document.documentElement;if(!matchMedia('(prefers-reduced-motion: reduce)').matches){d.classList.add('motion-ok');setTimeout(function(){if(!('revealReady' in d.dataset))d.classList.remove('motion-ok')},3000)}}catch(e){}})();`;

export function MotionScript() {
  return <script dangerouslySetInnerHTML={{ __html: motionScript }} />;
}

"use client";

import { inView } from "motion";
import {
  useEffect,
  useRef,
  type ComponentPropsWithoutRef,
  type ElementType,
  type ReactNode,
} from "react";

/**
 * Scroll-triggered reveal (fade + slight rise), fired once at ~20% in view.
 *
 * <Reveal> is a container. It reveals every descendant marked with `data-reveal`
 * (use <RevealItem> or spread `reveal` from ./reveal-attr), staggering them in DOM order.
 * Spread `reveal` on the <Reveal> itself to animate it too.
 *
 * Content is visible without JS / with reduced motion: the hidden state is only applied
 * under `html.motion-ok` (see firefly.css + <MotionScript> in the layout head).
 */
type RevealProps<T extends ElementType> = {
  as?: T;
  children: ReactNode;
  /** ms between staggered children (default 90) */
  stagger?: number;
  /** ms before the first child */
  delay?: number;
  /** fraction of the element that must be visible (default 0.2) */
  amount?: number;
} & Omit<ComponentPropsWithoutRef<T>, "as" | "children">;

export function Reveal<T extends ElementType = "div">({
  as,
  children,
  stagger = 90,
  delay = 0,
  amount = 0.2,
  ...rest
}: RevealProps<T>) {
  const Tag = (as ?? "div") as ElementType;
  const ref = useRef<HTMLElement>(null);

  useEffect(() => {
    const root = ref.current;
    if (!root) return;
    document.documentElement.dataset.revealReady = "";

    const items = Array.from(root.querySelectorAll<HTMLElement>("[data-reveal]"));
    const targets = root.hasAttribute("data-reveal") ? [root, ...items] : items;
    targets.forEach((el, i) => {
      el.style.setProperty("--reveal-delay", `${delay + i * stagger}ms`);
    });

    return inView(
      root,
      () => {
        targets.forEach((el) => el.setAttribute("data-in", ""));
      },
      { amount }
    );
  }, [amount, delay, stagger]);

  return (
    <Tag ref={ref} {...rest}>
      {children}
    </Tag>
  );
}

export function RevealItem<T extends ElementType = "div">({
  as,
  children,
  ...rest
}: { as?: T; children?: ReactNode } & Omit<ComponentPropsWithoutRef<T>, "as" | "children">) {
  const Tag = (as ?? "div") as ElementType;
  return (
    <Tag data-reveal="" {...rest}>
      {children}
    </Tag>
  );
}

/**
 * Spread onto any element inside <Reveal> to make it a staggered reveal child.
 * Lives outside the "use client" reveal module so Server Components get the real object
 * (values exported from a client module become client references and the animation never runs).
 */
export const reveal = { "data-reveal": "" } as const;

"use client";

import { motion, useReducedMotion, useScroll, useTransform } from "motion/react";
import { useEffect, useRef, useState, type ReactNode } from "react";

/**
 * Subtle vertical parallax for large visuals (transform only).
 *
 * mode "through" (default): drifts from +distance to -distance while the element crosses
 *   the viewport. For visuals further down the page (≈30px).
 * mode "exit": starts at 0 (renders exactly in place on load) and drifts down by `distance`
 *   as the element scrolls out. For the hero visual (≈60px).
 *
 * Disabled under prefers-reduced-motion.
 */
export function Parallax({
  children,
  distance = 30,
  mode = "through",
  className = "",
}: {
  children: ReactNode;
  distance?: number;
  mode?: "through" | "exit";
  className?: string;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const reduce = useReducedMotion();
  const { scrollYProgress } = useScroll({
    target: ref,
    offset: mode === "exit" ? ["start start", "end start"] : ["start end", "end start"],
  });
  const y = useTransform(scrollYProgress, (p) =>
    mode === "exit" ? p * distance : distance - p * 2 * distance
  );
  // The server can't know the motion preference, so the first client render matches the
  // server and the parallax is switched off right after hydration if needed.
  const [enabled, setEnabled] = useState(true);
  useEffect(() => setEnabled(!reduce), [reduce]);

  return (
    <div ref={ref} className={className}>
      <motion.div style={{ y: enabled ? y : 0 }} className="h-full w-full will-change-transform">
        {children}
      </motion.div>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

/**
 * Sets `--art-scale` on its parent element: max(1, parentWidth / designWidth).
 * Lets a decorative composition drawn at a fixed design width (1440px) grow to cover
 * wider screens via `scale-[var(--art-scale,1)]` instead of leaving empty bands.
 */
export function ArtScale({ designWidth = 1440 }: { designWidth?: number }) {
  const ref = useRef<HTMLSpanElement>(null);

  useEffect(() => {
    const parent = ref.current?.parentElement;
    if (!parent) return;
    const update = () =>
      parent.style.setProperty("--art-scale", String(Math.max(1, parent.clientWidth / designWidth)));
    update();
    const ro = new ResizeObserver(update);
    ro.observe(parent);
    return () => ro.disconnect();
  }, [designWidth]);

  return <span ref={ref} hidden />;
}

import Link from "next/link";
import type { ComponentPropsWithoutRef } from "react";

/**
 * Pill button, matched to the ElevenLabs reference: regular weight, three sizes, colour change
 * on hover (no lift), secondary = white with the half-pixel ring + soft shadow (no border).
 *
 * Variants: primary (black) · secondary (white, shadow) · on dark backgrounds: primary-on-dark
 * (white) · secondary-on-dark (transparent with a light ring). The old names dark / ghost /
 * light / ghost-dark still work as aliases.
 * Sizes: sm 36px (nav) · md 40px (tab bars, inline) · lg 44px (hero, section CTAs; default).
 */
export type ButtonVariant = "primary" | "secondary" | "primary-on-dark" | "secondary-on-dark" | "dark" | "ghost" | "light" | "ghost-dark";
export type ButtonSize = "sm" | "md" | "lg";

const ALIASES: Record<string, Exclude<ButtonVariant, "dark" | "ghost" | "light" | "ghost-dark">> = {
  dark: "primary",
  ghost: "secondary",
  light: "primary-on-dark",
  "ghost-dark": "secondary-on-dark",
};

export const buttonBase =
  "inline-flex shrink-0 cursor-pointer select-none items-center justify-center whitespace-nowrap rounded-pill font-normal " +
  "transition-[background-color,color,box-shadow] duration-150 ease-standard " +
  "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-border-interactive " +
  "disabled:pointer-events-none disabled:opacity-50 motion-reduce:transition-none";

export const buttonVariants = {
  primary: "bg-button-primary text-button-content-primary hover:bg-button-primary-hover",
  secondary: "bg-button-secondary text-button-content-secondary shadow-button hover:bg-button-secondary-hover",
  "primary-on-dark": "bg-surface-primary text-text-primary shadow-button hover:bg-button-secondary-hover",
  "secondary-on-dark": "bg-transparent text-text-on-dark shadow-[0_0_0_0.5px_rgba(255,255,255,0.3)] hover:bg-text-on-dark/10",
} as const;

export const buttonSizes: Record<ButtonSize, string> = {
  sm: "h-9 gap-1.5 px-3.5 text-[14px] leading-[21px]",
  md: "h-10 gap-1.5 px-4 text-[15px] leading-[22px]",
  lg: "h-11 gap-2 px-5 text-[16px] leading-[24px]",
};

export function buttonClasses(variant: ButtonVariant = "primary", size: ButtonSize = "lg", className = "") {
  const v = (ALIASES[variant] ?? variant) as keyof typeof buttonVariants;
  return `${buttonBase} ${buttonVariants[v]} ${buttonSizes[size]} ${className}`;
}

type Common = { variant?: ButtonVariant; size?: ButtonSize; className?: string };
type AsLink = Common & Omit<ComponentPropsWithoutRef<typeof Link>, "className"> & { href: string };
type AsButton = Common & Omit<ComponentPropsWithoutRef<"button">, "className"> & { href?: undefined };

/** Renders a Next <Link> when `href` is given, otherwise a native <button>. */
export function Button(props: AsLink | AsButton) {
  const { variant = "primary", size = "lg", className = "", ...rest } = props;
  const classes = buttonClasses(variant, size, className);
  if (rest.href !== undefined) {
    return <Link className={classes} {...(rest as AsLink)} />;
  }
  const { type = "button", ...buttonProps } = rest as AsButton;
  return <button type={type} className={classes} {...buttonProps} />;
}

import type { ComponentPropsWithoutRef } from "react";

/**
 * Round icon-only button (carousel arrows, close, play/pause). Secondary = white with the
 * button shadow, like the ElevenLabs testimonial arrows (32px, 16px chevron, 2px stroke).
 * Always pass `aria-label`.
 */
export type IconButtonSize = "sm" | "md" | "lg";
export type IconButtonVariant = "secondary" | "primary" | "secondary-on-dark";

const sizes: Record<IconButtonSize, string> = { sm: "size-8", md: "size-10", lg: "size-11" };
const variants: Record<IconButtonVariant, string> = {
  secondary: "bg-button-secondary text-button-content-secondary shadow-button hover:bg-button-secondary-hover",
  primary: "bg-button-primary text-button-content-primary hover:bg-button-primary-hover",
  "secondary-on-dark": "bg-transparent text-text-on-dark shadow-[0_0_0_0.5px_rgba(255,255,255,0.3)] hover:bg-text-on-dark/10",
};

export function IconButton({
  size = "sm",
  variant = "secondary",
  className = "",
  type = "button",
  ...rest
}: { size?: IconButtonSize; variant?: IconButtonVariant; className?: string } & ComponentPropsWithoutRef<"button"> & { "aria-label": string }) {
  return (
    <button
      type={type}
      className={`inline-flex shrink-0 cursor-pointer items-center justify-center rounded-pill transition-[background-color,color,box-shadow] duration-150 ease-standard focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-border-interactive disabled:pointer-events-none disabled:opacity-50 motion-reduce:transition-none ${sizes[size]} ${variants[variant]} ${className}`}
      {...rest}
    />
  );
}

/** 16px chevrons with a 2px stroke, for IconButton */
export function ChevronLeft({ className = "" }: { className?: string }) {
  return (
    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden className={className}>
      <path d="M10 3 5 8l5 5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}
export function ChevronRight({ className = "" }: { className?: string }) {
  return (
    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden className={className}>
      <path d="m6 3 5 5-5 5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}
export function PauseIcon({ className = "" }: { className?: string }) {
  return (
    <svg width="16" height="16" viewBox="0 0 16 16" fill="currentColor" aria-hidden className={className}>
      <rect x="4" y="3" width="3" height="10" rx="1" />
      <rect x="9" y="3" width="3" height="10" rx="1" />
    </svg>
  );
}
export function PlayIcon({ className = "" }: { className?: string }) {
  return (
    <svg width="16" height="16" viewBox="0 0 16 16" fill="currentColor" aria-hidden className={className}>
      <path d="M5 3.5v9l7-4.5-7-4.5Z" />
    </svg>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import { useId } from "react";

/**
 * Switch / tab pills (ElevenLabs "AI Voice Generator · Text to Speech · …"): 40px pills, regular
 * weight, the active one white with the button shadow. The white indicator slides between
 * items (transform only, 300ms); inactive items get a warm pressed layer on hover.
 * Keyboard: arrow keys move the selection, Home/End jump.
 */
export type SegmentedItem = { id: string; label: string };

export function Segmented({
  items,
  value,
  onChange,
  size = "md",
  ariaLabel = "Options",
  className = "",
}: {
  items: SegmentedItem[];
  value: string;
  onChange: (id: string) => void;
  size?: "sm" | "md";
  ariaLabel?: string;
  className?: string;
}) {
  const layoutId = useId();
  const reduce = useReducedMotion();
  const sizes = { sm: "h-9 px-3.5 text-[14px]", md: "h-10 px-4 text-[15px]" } as const;

  const onKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    const i = items.findIndex((it) => it.id === value);
    const go = (j: number) => {
      const next = items[(j + items.length) % items.length];
      onChange(next.id);
      (e.currentTarget.querySelectorAll<HTMLButtonElement>("[role=tab]")[(j + items.length) % items.length] ?? null)?.focus();
    };
    if (e.key === "ArrowRight" || e.key === "ArrowDown") go(i + 1);
    else if (e.key === "ArrowLeft" || e.key === "ArrowUp") go(i - 1);
    else if (e.key === "Home") go(0);
    else if (e.key === "End") go(items.length - 1);
    else return;
    e.preventDefault();
  };

  return (
    <div role="tablist" aria-label={ariaLabel} onKeyDown={onKeyDown} className={`inline-flex items-center gap-1 ${className}`}>
      {items.map((item) => {
        const active = item.id === value;
        return (
          <button
            key={item.id}
            type="button"
            role="tab"
            aria-selected={active}
            tabIndex={active ? 0 : -1}
            onClick={() => onChange(item.id)}
            className={`relative inline-flex cursor-pointer items-center justify-center whitespace-nowrap rounded-pill font-normal leading-none transition-[color,background-color] duration-150 ease-standard focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-border-interactive motion-reduce:transition-none ${sizes[size]} ${
              active ? "text-text-primary" : "text-text-primary hover:bg-surface-pressed"
            }`}
          >
            {active ? (
              <motion.span
                layoutId={layoutId}
                aria-hidden
                className="absolute inset-0 rounded-pill bg-button-secondary shadow-button"
                transition={reduce ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 40, mass: 0.6 }}
              />
            ) : null}
            <span className="relative">{item.label}</span>
          </button>
        );
      })}
    </div>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import { useId } from "react";

/**
 * Carousel pagination (ElevenLabs testimonials): 4px warm-grey dots, the active one stretched
 * into a 24×4 dark line that slides between positions (transform only). Each dot is a button
 * with a 20px-tall hit area.
 */
export function PaginationDots({
  count,
  index,
  onSelect,
  label = "Go to slide",
  className = "",
}: {
  count: number;
  index: number;
  onSelect: (i: number) => void;
  /** Accessible name prefix: "Go to slide 3" */
  label?: string;
  className?: string;
}) {
  const layoutId = useId();
  const reduce = useReducedMotion();
  return (
    <div className={`flex items-center ${className}`} role="group" aria-label="Slides">
      {Array.from({ length: count }, (_, i) => {
        const active = i === index;
        return (
          <button
            key={i}
            type="button"
            aria-label={`${label} ${i + 1}`}
            aria-current={active ? "true" : undefined}
            onClick={() => onSelect(i)}
            className={`relative flex h-5 cursor-pointer items-center justify-center px-1 transition-[width] duration-300 ease-standard focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-border-interactive motion-reduce:transition-none ${active ? "w-8" : "w-3"}`}
          >
            <span aria-hidden className={`block size-1 rounded-pill bg-pagination-dot transition-opacity duration-150 ${active ? "opacity-0" : "opacity-100"}`} />
            {active ? (
              <motion.span
                layoutId={layoutId}
                aria-hidden
                className="absolute left-1 top-2 h-1 w-6 rounded-pill bg-pagination-active"
                transition={reduce ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 40, mass: 0.6 }}
              />
            ) : null}
          </button>
        );
      })}
    </div>
  );
}

import { Button } from "@/components/ui/button";

export type CtaLink = { label: string; href: string };

/**
 * Call-to-action pair used in heroes and closing sections: primary pill + secondary pill,
 * 44px, 8px apart (the ElevenLabs "Sign up · Contact sales" pair). Pass `onDark` on dark sections.
 */
export function HeroCta({
  primary = { label: "Join waitlist", href: "#cta" },
  secondary = { label: "Book a demo", href: "#cta" },
  onDark = false,
  size = "lg",
  className = "",
}: {
  primary?: CtaLink;
  secondary?: CtaLink | null;
  onDark?: boolean;
  size?: "sm" | "md" | "lg";
  className?: string;
}) {
  return (
    <div className={`flex flex-wrap items-center gap-2 ${className}`}>
      <Button href={primary.href} variant={onDark ? "primary-on-dark" : "primary"} size={size}>
        {primary.label}
      </Button>
      {secondary ? (
        <Button href={secondary.href} variant={onDark ? "secondary-on-dark" : "secondary"} size={size}>
          {secondary.label}
        </Button>
      ) : null}
    </div>
  );
}

/**
 * Two-tone headline text: the first part in the primary colour, the second half in the
 * muted grey (house rule for every h1/h2). Renders inside the heading element you own:
 *
 *   <h2 className="..."><TwoTone text="Three weeks of diligence." muted="Or twelve minutes." /></h2>
 *
 * `stack` puts the muted part on its own line (display headlines).
 */
export function TwoTone({
  text,
  muted,
  stack = false,
  onDark = false,
}: {
  text: string;
  muted?: string;
  stack?: boolean;
  onDark?: boolean;
}) {
  if (!muted) return <>{text}</>;
  const mutedClass = onDark ? "text-text-on-dark/60" : "text-text-muted";
  return (
    <>
      <span className={stack ? "block" : undefined}>{text}</span>
      {stack ? null : " "}
      <span className={`${mutedClass} ${stack ? "block" : ""}`}>{muted}</span>
    </>
  );
}

